'use strict';
(function(){
  const esc=escapeText,phases={waiting:'รอเข้าห้อง',pretest:'คำถามก่อนเรียน',briefing:'เรียนรู้และวางแผน',play:'ภารกิจในสนาม',checkpoint:'คำถามระหว่างเกม',posttest:'คำถามหลังเรียน',reflection:'สะท้อนคิด',finished:'สรุปการเรียนรู้'};
  const clone=value=>typeof structuredClone==='function'?structuredClone(value):JSON.parse(JSON.stringify(value));
  let teacherEntry=0,teacher=null,banks=[],draft=null,index=0,currentClass=null,teacherTimer=null,studentTimer=null,renderKey='',lastTeacherKey='',reflectionDraft={knowledge:'',teamwork:''};
  try{teacher=JSON.parse(localStorage.getItem('rift.teacher'));education.session=JSON.parse(sessionStorage.getItem('rift.classStudent'));}catch{}
  const root=document.createElement('section');root.id='classroom';root.hidden=true;root.setAttribute('aria-label','ห้องเรียน Rift Arena');document.body.appendChild(root);
  const bar=document.createElement('button');bar.id='classLessonBar';bar.hidden=true;document.body.appendChild(bar);
  function message(s){const el=$('lessonMessage');if(el)el.textContent=s;}
  function shell(title,body){root.innerHTML=`<div class="lesson-shell"><header class="lesson-header"><div><span class="lesson-eyebrow">RIFT CLASSROOM · V13</span><h1>${esc(title)}</h1></div><button id="lessonBack">หน้าเลือกโหมด</button></header><div id="lessonMessage" role="status" aria-live="polite"></div>${body}</div>`;$('lessonBack').onclick=home;}
  function home(role='choice'){teacherEntry++;clearInterval(teacherTimer);clearInterval(studentTimer);detachClassMatch();bar.hidden=true;root.hidden=false;document.body.classList.add('education-open');
    const studentForm=`<section class="lesson-card student-entry"><h2>นักเรียน · เข้าห้องเรียน</h2><p>สแกน QR ที่ครูแสดง หรือกรอกรหัสห้อง</p><button id="scanClassQr" type="button">สแกน QR เข้าห้องเรียน</button><form id="studentJoin"><label>รหัสห้องเรียน<input id="classCode" maxlength="6" autocomplete="off" required placeholder="รหัส 6 ตัวจากครู"></label><label>ชื่อเล่นหรือเลขที่<input id="studentName" maxlength="30" required autocomplete="off"></label><label>ฮีโร่<select id="studentHero">${HEROES.map(h=>`<option value="${h.id}">${esc(h.name)}</option>`).join('')}</select></label><button class="lesson-primary" type="submit">เข้าห้องเรียน</button></form>${education.session?'<button id="resumeClass">กลับเข้าห้องเรียนเดิม</button>':''}</section>`;
    shell(role==='student'?'นักเรียน · เข้าห้องเรียน':'เลือกครูหรือนักเรียน',role==='student'?studentForm:`<div class="lesson-role-grid simple-roles"><section class="lesson-card teacher-entry"><span class="role-label">สำหรับครู</span><h2>สร้างห้องให้นักเรียน</h2><p>เลือกชุดคำถาม แล้วเปิด QR ให้ทั้งห้องสแกน</p><button id="teacherEnter" class="lesson-primary role-button" type="button">ครู · สร้างห้องเรียน</button><p class="lesson-note">รองรับ 50 คน · ใช้ชุดตัวอย่างได้ทันที<br>แก้ไขหรือเพิ่มคำถามของครูได้</p><button id="teacherBanksEnter" type="button">แก้ไขชุดคำถาม</button></section><section class="lesson-card"><span class="role-label">สำหรับนักเรียน</span><h2>เข้าห้องที่ครูสร้าง</h2><p>ใช้ QR หรือรหัสห้องจากครู</p><button id="studentEnter" class="role-button" type="button">นักเรียน · เข้าห้องเรียน</button></section></div>`);
    if($('teacherEnter'))$('teacherEnter').onclick=()=>teacherHome('create');if($('teacherBanksEnter'))$('teacherBanksEnter').onclick=()=>teacherHome('banks');if($('studentEnter'))$('studentEnter').onclick=()=>home('student');
    if($('studentJoin')){$('studentJoin').onsubmit=joinStudent;$('scanClassQr').onclick=()=>window.RiftJoin.scan();if($('resumeClass'))$('resumeClass').onclick=studentHome;const code=new URLSearchParams(location.search).get('class');if(code&&/^[A-Z0-9]{6}$/.test(code))$('classCode').value=code;}
    $('lessonBack').textContent=role==='student'?'เลือกครู / นักเรียน':'กลับหน้าเกม';$('lessonBack').onclick=role==='student'?()=>home():()=>{teacherEntry++;sessionStorage.setItem('rift.classActive','0');root.hidden=true;document.body.classList.remove('education-open');};
  }
  async function teacherHome(view='create'){
    if(view!=='banks')view='create';const ticket=++teacherEntry;clearInterval(studentTimer);clearInterval(teacherTimer);detachClassMatch();bar.hidden=true;root.hidden=false;document.body.classList.add('education-open');shell(view==='banks'?'แก้ไขชุดคำถาม':'ครู · สร้างห้องเรียน','<section class="lesson-card teacher-loading" role="status"><h2>กำลังเตรียมหน้าครู…</h2><p>โหลดชุดคำถามที่บันทึกไว้บนเครื่องนี้</p></section>');
    try{if(!teacher?.token){const account=await lessonRequest('teachers','POST',{},null);teacher=account;try{localStorage.setItem('rift.teacher',JSON.stringify(teacher));}catch{}}
      const d=await lessonRequest('lesson-banks','GET',undefined,teacher.token);if(ticket!==teacherEntry)return;banks=d.banks;if(!banks.length)throw Error('ยังไม่มีชุดคำถาม กรุณาเปิดคลังคำถามอีกครั้ง');draft=clone(banks[0]);index=0;if(view==='banks')renderTeacherHome();else renderTeacherCreate();
    }catch(e){if(ticket!==teacherEntry)return;shell('เปิดหน้าครูยังไม่สำเร็จ',`<section class="lesson-card teacher-error"><h2>ลองเปิดหน้าครูอีกครั้ง</h2><p>${esc(e.message)}</p><button id="retryTeacher" class="lesson-primary" type="button">ลองใหม่</button><button id="teacherErrorBack" type="button">เลือกครู / นักเรียน</button></section>`);$('retryTeacher').onclick=()=>teacherHome(view);$('teacherErrorBack').onclick=()=>home();}
  }
  function renderTeacherCreate(){
    shell('ครู · สร้างห้องเรียน',`<div class="teacher-create-layout"><section class="lesson-card quick-class"><span class="role-label">เลือกชุดคำถาม แล้วสร้างห้องได้เลย</span><h2>สร้างห้องสำหรับนักเรียน 50 คน</h2><form id="createClassForm"><label>วิชา / ชุดคำถาม<select id="classBank">${banks.map(b=>`<option value="${b.id}" ${b.id===draft?.id?'selected':''}>${esc(b.subject)} · ${esc(b.title)}</option>`).join('')}</select></label><p id="selectedBankInfo" class="bank-info"></p><label>ชื่อห้อง <span class="optional-label">ไม่กรอกก็ได้</span><input id="classTitle" maxlength="160" placeholder="ใช้ชื่อชุดคำถามอัตโนมัติ"></label><label>รูปแบบการเล่น<select id="classArenaMode"><option value="split">แบ่ง 5 สนาม · สนามละ 10 คน</option><option value="mass">รวมสนามเดียว · 50 คน</option></select></label><details class="class-extra"><summary>ปรับเวลาและภารกิจเพิ่มเติม</summary><label>เวลาเล่น (นาที)<input id="classMinutes" type="number" min="2" max="30" value="8"></label><label>ภารกิจของทีม<textarea id="classMission" rows="3" maxlength="500">แบ่งหน้าที่ สื่อสารด้วยเหตุผล แล้วอธิบายว่าความรู้ในบทเรียนช่วยให้ทีมตัดสินใจอย่างไร</textarea></label></details><button id="createClassBtn" class="lesson-primary create-class-action" type="submit">สร้างห้องและแสดง QR</button><p class="lesson-note">เริ่มด้วยชุดตัวอย่างได้ทันที · เวลาเล่นเริ่มต้น 8 นาที</p></form><button id="editTeacherBanks" type="button">แก้ไข / เพิ่มชุดคำถาม</button></section><aside class="lesson-card teacher-past"><h2>ห้องที่สร้างไว้</h2><div id="pastClasses">กำลังโหลด…</div></aside></div>`);
    $('lessonBack').textContent='เลือกครู / นักเรียน';$('lessonBack').onclick=()=>home();$('createClassForm').onsubmit=createClass;$('editTeacherBanks').onclick=renderTeacherHome;
    const describe=()=>{const selected=banks.find(b=>b.id===$('classBank').value);$('selectedBankInfo').textContent=selected?selected.questions.length+' ข้อ · '+selected.level:'';};$('classBank').onchange=describe;describe();void loadPast();
  }
  function renderTeacherHome(){shell('แก้ไขชุดคำถาม',`<div class="teacher-bank-toolbar"><button id="teacherQuickCreate" class="lesson-primary" type="button">กลับไปสร้างห้องเรียน</button></div><div class="teacher-bank-page"><section class="lesson-card bank-editor"><div class="lesson-section-title"><h2>ชุดคำถาม</h2><button id="newBank">ชุดใหม่</button></div><label>เลือกชุดคำถาม<select id="bankSelect">${banks.map(b=>`<option value="${b.id}" ${b.id===draft?.id?'selected':''}>${esc(b.subject)} · ${esc(b.title)}</option>`).join('')}${draft?.id?'':'<option value="" selected>ชุดใหม่ที่ยังไม่บันทึก</option>'}</select></label><div class="lesson-fields"><label>ชื่อชุด<input id="bankTitle" maxlength="160" value="${esc(draft?.title||'')}"></label><label>วิชา<input id="bankSubject" maxlength="60" value="${esc(draft?.subject||'')}"></label><label>ระดับชั้น<input id="bankLevel" maxlength="80" value="${esc(draft?.level||'')}"></label></div><div class="question-nav"><div id="questionTabs"></div><button id="addQuestion">เพิ่มคำถาม</button></div><div id="questionEditor"></div><div class="lesson-buttons"><button id="saveBank" class="lesson-primary">บันทึกชุดคำถาม</button><button id="exportBank">ส่งออกชุด JSON</button><label class="file-button">นำเข้าชุด JSON<input type="file" id="importBank" accept="application/json,.json"></label></div><p class="lesson-note">มีชุดตัวอย่าง 8 กลุ่มวิชา แก้เนื้อหาและระดับชั้นได้ หรือสร้างวิชาอื่นเอง · บันทึกก่อนนำไปเปิดห้อง</p></section></div>`);
    $('bankSelect').onchange=()=>{draft=clone(banks.find(b=>b.id===$('bankSelect').value));index=0;renderTeacherHome();};$('newBank').onclick=()=>{draft={title:'',subject:'',level:'',questions:[blankQuestion()]};index=0;renderTeacherHome();};$('addQuestion').onclick=()=>{captureDraft();if(draft.questions.length>=40)return message('ชุดหนึ่งมีได้สูงสุด 40 ข้อ');draft.questions.push(blankQuestion());index=draft.questions.length-1;renderQuestion();};$('saveBank').onclick=saveBank;$('exportBank').onclick=()=>{captureDraft();download(JSON.stringify({...draft,id:undefined},null,2),(draft.subject||'lesson')+'-questions.json','application/json');};$('importBank').onchange=importBank;$('teacherQuickCreate').onclick=()=>{captureDraft();renderTeacherCreate();};renderQuestion();void loadPast();
  }
  function blankQuestion(){return {id:crypto.randomUUID(),prompt:'',options:['','','',''],correct:0,explanation:''};}
  function captureDraft(){if(!draft)return;draft.title=$('bankTitle').value;draft.subject=$('bankSubject').value;draft.level=$('bankLevel').value;const q=draft.questions[index];if(q&&$('questionPrompt')){q.prompt=$('questionPrompt').value;q.options=[0,1,2,3].map(n=>$('answer'+n).value);q.correct=Number($('correctAnswer').value);q.explanation=$('questionExplanation').value;}}
  function renderQuestion(){const q=draft.questions[index];$('questionTabs').innerHTML=draft.questions.map((_,n)=>`<button data-question-index="${n}" class="${n===index?'active':''}">ข้อ ${n+1}</button>`).join('');$('questionTabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{captureDraft();index=Number(b.dataset.questionIndex);renderQuestion();});$('questionEditor').innerHTML=`<div class="lesson-section-title"><h3>ข้อ ${index+1} / ${draft.questions.length}</h3><button id="removeQuestion" ${draft.questions.length===1?'disabled':''}>ลบข้อนี้</button></div><label>โจทย์<textarea id="questionPrompt" rows="3" maxlength="500">${esc(q.prompt)}</textarea></label><div class="lesson-answer-fields">${q.options.map((v,n)=>`<label>ตัวเลือก ${String.fromCharCode(65+n)}<input id="answer${n}" maxlength="180" value="${esc(v)}"></label>`).join('')}</div><label>คำตอบที่ถูกต้อง<select id="correctAnswer">${q.options.map((_,n)=>`<option value="${n}" ${q.correct===n?'selected':''}>ตัวเลือก ${String.fromCharCode(65+n)}</option>`).join('')}</select></label><label>คำอธิบายเฉลย<textarea id="questionExplanation" rows="2" maxlength="700">${esc(q.explanation)}</textarea></label>`;$('removeQuestion').onclick=()=>{captureDraft();draft.questions.splice(index,1);index=Math.min(index,draft.questions.length-1);renderQuestion();};}
  async function saveBank(){captureDraft();$('saveBank').disabled=true;try{const saved=await lessonRequest('lesson-banks'+(draft.id?'/'+draft.id:''),draft.id?'PUT':'POST',draft,teacher.token);const all=await lessonRequest('lesson-banks','GET',undefined,teacher.token);banks=all.banks;draft=clone(banks.find(b=>b.id===saved.id));renderTeacherHome();message('บันทึกชุดคำถามแล้ว');}catch(e){message(e.message);}finally{if($('saveBank'))$('saveBank').disabled=false;}}
  async function importBank(){const file=$('importBank').files[0];if(!file)return;try{if(file.size>200000)throw Error('ไฟล์ต้องเล็กกว่า 200 KB');const b=JSON.parse(await file.text());if(!Array.isArray(b.questions)||!b.questions.length||b.questions.length>40)throw Error('ไฟล์ต้องมีคำถาม 1–40 ข้อ');draft={title:String(b.title||''),subject:String(b.subject||''),level:String(b.level||''),questions:b.questions.map(q=>({...blankQuestion(),...q,id:crypto.randomUUID()}))};if(draft.questions.some(q=>!Array.isArray(q.options)||q.options.length!==4))throw Error('แต่ละข้อต้องมีตัวเลือก 4 ข้อ');index=0;renderTeacherHome();message('นำเข้าแล้ว ตรวจและบันทึกชุดคำถาม');}catch(e){message(e.message);}}
  async function loadPast(){try{const d=await lessonRequest('classes','GET',undefined,teacher.token);if(!$('pastClasses'))return;$('pastClasses').innerHTML=d.classes.length?d.classes.map(c=>`<button class="past-class" data-class-id="${c.id}"><b>${esc(c.title)}</b><span>${c.id} · ${phases[c.phase]}</span></button>`).join(''):'ยังไม่มีห้องเรียน';$('pastClasses').querySelectorAll('button').forEach(b=>b.onclick=()=>openTeacherClass(b.dataset.classId));}catch(e){message(e.message);}}
  async function createClass(e){e.preventDefault();const button=e.target.querySelector('button[type="submit"]');button.disabled=true;const label=button.textContent;button.textContent='กำลังสร้างห้อง…';message('');try{const d=await lessonRequest('classes','POST',{bankId:$('classBank').value,title:$('classTitle').value,mode:$('classArenaMode').value,minutes:Number($('classMinutes').value),mission:$('classMission').value},teacher.token);await openTeacherClass(d.code);if($('classQrBtn'))void window.RiftJoin.share('class',d.code);}catch(e){message(e.message);if(button.isConnected){button.disabled=false;button.textContent=label;}} }
  async function openTeacherClass(code){currentClass=code;lastTeacherKey='';clearInterval(teacherTimer);shell('ห้องเรียน '+code,`<div id="teacherClassContent">กำลังโหลดห้องเรียน…</div>`);await pollTeacher();teacherTimer=setInterval(()=>void pollTeacher(),2000);}
  async function pollTeacher(){if(!currentClass||education.busy)return;education.busy=true;try{const d=await lessonRequest(`classes/${currentClass}/teacher`,'GET',undefined,teacher.token);const key=JSON.stringify({...d,students:d.students.map(({seen_at,seq,...p})=>({...p,online:Date.now()-seen_at<10000})),matches:d.matches.map(({updatedAt,time,...m})=>({...m,stale:Date.now()-updatedAt>12000}))});if(key!==lastTeacherKey){const focused=$('checkpointQuestion')===document.activeElement;if(!focused){const selected=$('checkpointQuestion')?.value;const opened=Array.from($('teacherClassContent')?.querySelectorAll('details')||[]).map(x=>x.open);renderTeacherClass(d);if(selected&&$('checkpointQuestion'))$('checkpointQuestion').value=selected;Array.from($('teacherClassContent')?.querySelectorAll('details')||[]).forEach((x,i)=>x.open=!!opened[i]);lastTeacherKey=key;}}}catch(e){message(e.message);}finally{education.busy=false;}}
  const aggregate=(p,stage)=>p.scores.filter(s=>s.stage===stage).reduce((r,s)=>({answered:r.answered+s.answered,correct:r.correct+s.correct}),{answered:0,correct:0});
  function renderTeacherClass(d){if(!$('teacherClassContent'))return;const n=d.lesson.questions.length,completed=d.students.filter(p=>aggregate(p,['pretest','posttest'].includes(d.phase)?d.phase:'pretest').answered===n).length;const online=d.students.filter(p=>Date.now()-p.seen_at<10000).length;
    $('teacherClassContent').innerHTML=`${d.phase==='waiting'?'<div class="teacher-start-guide"><b>ห้องพร้อมแล้ว</b><span>แสดง QR ให้นักเรียน · รอเข้าห้อง · กดเริ่มคำถามก่อนเรียน</span></div>':''}<section class="class-summary"><div><span class="lesson-eyebrow">รหัสเข้าห้อง</span><strong class="class-code">${d.code}</strong><button id="classQrBtn">แสดง QR ให้นักเรียน</button><button id="copyClassLink">คัดลอกลิงก์ให้นักเรียน</button></div><div><h2>${esc(d.title)}</h2><p>${esc(d.lesson.subject)} · ${esc(d.lesson.level)} · ${d.mode==='mass'?'สนามเดียว 25 ต่อ 25':'5 สนาม 5 ต่อ 5'}</p><p class="mission-copy">${esc(d.mission)}</p></div><div class="class-count"><strong>${d.students.length}<small> / 50 คน</small></strong><span>เชื่อมต่อ ${online} คน · แบบทดสอบครบ ${completed} คน</span></div></section><section class="lesson-card teacher-controls"><div><span class="lesson-eyebrow">ช่วงกิจกรรม</span><h2>${phases[d.phase]}${d.paused?' · พักอยู่':''}</h2></div><div class="lesson-buttons"><button id="nextClassPhase" class="lesson-primary" ${d.phase==='finished'?'disabled':''}>${{waiting:'เริ่มคำถามก่อนเรียน',pretest:'เปิดบทเรียนและเฉลย',briefing:'เริ่มภารกิจในสนาม',checkpoint:'กลับเข้าสู่สนาม',play:'เริ่มคำถามหลังเรียน',posttest:'เปิดสะท้อนคิด',reflection:'จบกิจกรรม',finished:'จบกิจกรรมแล้ว'}[d.phase]}</button><button id="pauseClass" ${d.phase!=='play'?'disabled':''}>${d.paused?'เล่นต่อทั้งห้อง':'พักทั้งห้อง'}</button><button id="exportClassReport">รายงาน CSV</button><button id="teacherBankBack">กลับคลังคำถาม</button></div>${d.phase==='play'?`<div class="checkpoint-control"><select id="checkpointQuestion" aria-label="โจทย์ระหว่างเกม">${d.lesson.questions.map((q,i)=>`<option value="${q.id}">ข้อ ${i+1}: ${esc(q.prompt)}</option>`).join('')}</select><button id="askCheckpoint">หยุดสนามเพื่อถามโจทย์นี้</button></div>`:''}</section><div class="arena-cards">${d.matches.map(m=>`<section class="lesson-card"><h3>สนาม ${m.arena+1}</h3><p>${d.students.filter(p=>p.arena===m.arena).length} คน · ${m.status==='waiting'?'รอเริ่ม':m.finished?'จบแมตช์':Date.now()-m.updatedAt>12000?'กำลังรอผู้ดูแลสนาม':'กำลังเล่น'}</p><span>ทีมฟ้า ${m.kills[0]} : ${m.kills[1]} ทีมส้ม</span></section>`).join('')}</div><section class="lesson-card"><h2>คะแนนคำถามและการสะท้อนคิด</h2><p class="lesson-note">แยกจากคิลและผลแพ้ชนะ · “—” หมายถึงยังไม่ได้ตอบ · คะแนนที่ตอบไม่ครบระบุจำนวนข้อที่ส่งแล้ว</p><div class="lesson-table-wrap"><table><thead><tr><th>นักเรียน</th><th>สนาม / ทีม</th><th>ก่อนเรียน</th><th>หลังเรียน</th><th>เปลี่ยนแปลง</th><th>สะท้อนคิด</th></tr></thead><tbody>${d.students.map(p=>{const pre=aggregate(p,'pretest'),post=aggregate(p,'posttest');let reflection;try{reflection=JSON.parse(p.reflection);}catch{}return `<tr><td>${esc(p.name)}</td><td>${p.arena+1} / ${p.team===0?'ฟ้า':'ส้ม'}</td><td>${pre.answered?pre.correct+' / '+n+' · ส่ง '+pre.answered+' ข้อ':'—'}</td><td>${post.answered?post.correct+' / '+n+' · ส่ง '+post.answered+' ข้อ':'—'}</td><td>${pre.answered===n&&post.answered===n?(post.correct-pre.correct>=0?'+':'')+(post.correct-pre.correct):'—'}</td><td>${reflection?`<details><summary>ส่งแล้ว</summary><p>${esc(reflection.knowledge)}</p><p>${esc(reflection.teamwork)}</p></details>`:'ยังไม่ส่ง'}</td></tr>`;}).join('')}</tbody></table></div></section><section class="lesson-card"><h2>ข้อที่ควรทบทวนร่วมกัน</h2><div class="lesson-question-review">${d.lesson.questions.map((q,i)=>{const rows=d.answers.filter(a=>a.question_id===q.id&&a.stage==='posttest'),wrong=rows.filter(a=>!a.correct).length;return `<details><summary>ข้อ ${i+1} · หลังเรียนตอบผิด ${wrong} จาก ${rows.length} คน — ${esc(q.prompt)}</summary><p>คำตอบ: ${esc(q.options[q.correct])}</p><p>${esc(q.explanation)}</p></details>`;}).join('')}</div></section><p class="lesson-note">ผู้ดูแลสนามเป็นเครื่องของนักเรียนที่ระบบเลือกให้ ควรเปิดแท็บไว้ หากขาดการเชื่อมต่อระบบจะเลือกผู้ดูแลใหม่ · คะแนนและคำตอบบันทึกที่ห้องเรียน</p>`;
    $('nextClassPhase').onclick=()=>controlClass({action:'next'});$('pauseClass').onclick=()=>controlClass({action:d.paused?'resume':'pause'});$('teacherBankBack').textContent='สร้างห้องใหม่';$('teacherBankBack').onclick=()=>teacherHome('create');$('exportClassReport').onclick=()=>exportReport(d);if($('askCheckpoint'))$('askCheckpoint').onclick=()=>controlClass({action:'checkpoint',questionId:$('checkpointQuestion').value});$('classQrBtn').onclick=()=>window.RiftJoin.share('class',d.code);$('copyClassLink').onclick=async()=>{try{await navigator.clipboard.writeText(location.origin+'/?class='+d.code);message('คัดลอกลิงก์แล้ว');}catch{message('รหัสห้องเรียน: '+d.code);}};
  }
  async function controlClass(value){const button=$('nextClassPhase');if(button)button.disabled=true;try{await lessonRequest(`classes/${currentClass}/control`,'POST',value,teacher.token);lastTeacherKey='';await pollTeacher();}catch(e){message(e.message);if(button)button.disabled=false;}}
  function exportReport(d){const rows=[['ชื่อเล่น/เลขที่','สนาม','ทีม','วิชา','จำนวนข้อ','ก่อนเรียนถูก','ก่อนเรียนส่ง','หลังเรียนถูก','หลังเรียนส่ง','เปลี่ยนแปลงเมื่อส่งครบ','คำถามระหว่างเกมถูก','ความรู้ที่ใช้','การทำงานเป็นทีม','คิล','ตาย','ช่วย']];for(const p of d.students){const pre=aggregate(p,'pretest'),post=aggregate(p,'posttest'),check=aggregate(p,'checkpoint');let reflection={};try{reflection=JSON.parse(p.reflection)||{};}catch{}const stats=d.matches.flatMap(m=>m.players).find(e=>e.id===p.id)||{};rows.push([p.name,p.arena+1,p.team===0?'ฟ้า':'ส้ม',d.lesson.subject,d.lesson.questions.length,pre.answered?pre.correct:'',pre.answered,post.answered?post.correct:'',post.answered,pre.answered===d.lesson.questions.length&&post.answered===d.lesson.questions.length?post.correct-pre.correct:'',check.correct,reflection.knowledge||'',reflection.teamwork||'',stats.kills??'',stats.deaths??'',stats.assists??'']);}const cell=v=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};download('\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'classroom-'+d.code+'.csv','text/csv;charset=utf-8');}
  function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  async function joinStudent(e){e.preventDefault();const code=$('classCode').value.trim().toUpperCase();if(!/^[A-Z0-9]{6}$/.test(code))return message('กรอกรหัสห้องเรียน 6 ตัว');const button=e.target.querySelector('button');button.disabled=true;try{education.session=await lessonRequest(`classes/${code}/join`,'POST',{name:$('studentName').value,hero:$('studentHero').value},null);sessionStorage.setItem('rift.classStudent',JSON.stringify(education.session));reflectionDraft={knowledge:'',teamwork:''};await studentHome();}catch(e){message(e.message);button.disabled=false;}}
  async function studentHome(){sessionStorage.setItem('rift.classActive','1');clearInterval(teacherTimer);clearInterval(studentTimer);root.hidden=false;document.body.classList.add('education-open');renderKey='';shell('ห้องเรียน '+education.session.code,'<div id="studentClassContent">กำลังกลับเข้าห้องเรียน…</div>');await pollStudent();studentTimer=setInterval(()=>void pollStudent(),1500);}
  async function pollStudent(){if(!education.session||education.busy)return;education.busy=true;try{const d=await lessonRequest(`classes/${education.session.code}`);education.details=d;if(d.phase==='play'){await connectClassMatch();if(game){game.paused=d.paused;root.hidden=!(d.paused||education.panelOpen||game.finished);document.body.classList.toggle('education-open',!root.hidden);bar.hidden=false;bar.textContent=d.title+' · '+(d.paused?'ครูพักสนาม':d.mission);}}
    else{if(game)game.paused=true;education.panelOpen=false;root.hidden=false;document.body.classList.add('education-open');bar.hidden=true;$('result').hidden=true;$('pauseOverlay').hidden=true;}
    const key=[d.phase,d.paused,d.round,d.memberCount,d.answers.length,d.student.reflection].join(':');if(key!==renderKey){renderStudent(d);renderKey=key;}if($('studentClock'))$('studentClock').textContent=d.phase==='play'&&!d.paused&&d.deadline?'เหลือ '+Math.max(0,Math.ceil((d.deadline-Date.now())/60000))+' นาที':'';
  }catch(e){message(e.message);}finally{education.busy=false;}}
  function renderStudent(d){if(!$('studentClassContent'))shell('ห้องเรียน '+d.code,'<div id="studentClassContent"></div>');const qs=d.phase==='checkpoint'?d.lesson.questions.filter(q=>q.id===d.focus):d.lesson.questions,ans=d.answers.filter(a=>a.stage===d.phase&&a.round===d.round),pre=d.answers.filter(a=>a.stage==='pretest'),post=d.answers.filter(a=>a.stage==='posttest');let body='';
    if(d.phase==='waiting')body=`<section class="lesson-card student-wait"><strong>${d.memberCount} / 50 คน</strong><h2>รอครูเริ่มกิจกรรม</h2><p>สนาม ${d.student.arena+1} · ทีม${d.student.team===0?'ฟ้า':'ส้ม'} · ${POSITIONS[d.student.position]}</p><p>${d.mode==='mass'?'ทั้งห้องอยู่ในสนาม 25 ต่อ 25':'ระบบแบ่งนักเรียนลงสนามละ 10 คน ตำแหน่งที่ว่างจะเป็นบอต'}</p><ol class="student-checklist"><li>ฮีโร่ของคุณ: ${esc(HEROES.find(h=>h.id===d.student.hero)?.name||d.student.hero)}</li><li>ตอบคำถามก่อนเรียน แล้ววางแผนกับเพื่อนในทีม</li><li>หมุนจอแนวนอน · จอยซ้ายเดิน · ลากปุ่มสกิลเพื่อเล็ง</li><li>ถ้าภาพกระตุก เลือกภาพ: ประหยัด และปิดแอปอื่น</li></ol></section>`;
    if(['pretest','posttest','checkpoint'].includes(d.phase))body=`<div class="quiz-progress">ส่งแล้ว ${ans.length} / ${qs.length} ข้อ · ตอบได้ครั้งเดียวต่อช่วง</div><div class="quiz-questions">${qs.map((q,i)=>{const a=ans.find(a=>a.question_id===q.id);return `<section class="lesson-card quiz-question"><h2>${i+1}. ${esc(q.prompt)}</h2><div class="quiz-options">${q.options.map((v,n)=>`<button data-answer-question="${q.id}" data-choice="${n}" ${a?'disabled':''} class="${a?.answer===n?'chosen':''}"><b>${String.fromCharCode(65+n)}</b>${esc(v)}</button>`).join('')}</div>${a?'<p class="answer-saved">บันทึกคำตอบแล้ว</p>':''}</section>`;}).join('')}</div><p>เมื่อตอบครบ รอครูเปิดช่วงถัดไป</p>`;
    if(d.phase==='briefing')body=`<section class="lesson-card"><h2>ทบทวนก่อนเข้าสนาม</h2><p>${esc(d.mission)}</p><p>คุยกับเพื่อนว่าใครรับหน้าที่อะไร และจะใช้ความรู้ในบทเรียนอย่างไร</p></section>${d.lesson.questions.map((q,i)=>`<details class="lesson-card"><summary>ข้อ ${i+1}: ${esc(q.prompt)}</summary><p>คำตอบ: ${esc(q.options[q.correct])}</p><p>${esc(q.explanation)}</p></details>`).join('')}<p>รอครูเริ่มภารกิจในสนาม</p>`;
    if(d.phase==='play')body=`<section class="lesson-card"><h2>${d.paused?'ครูพักสนามเพื่ออธิบาย':game?.finished?'สนามจบแล้ว · รอครูเปิดคำถามหลังเรียน':'ภารกิจของทีม'}</h2><p>${esc(d.mission)}</p><p id="studentClock"></p><button id="returnClassGame" class="lesson-primary" ${d.paused||game?.finished?'disabled':''}>กลับเข้าสนาม</button></section>`;
    if(d.phase==='reflection'||d.phase==='finished'){let saved={};try{saved=JSON.parse(d.student.reflection)||{};}catch{}if(saved.knowledge&&!reflectionDraft.knowledge)reflectionDraft=saved;body=`<section class="lesson-card"><h2>ผลคำถามของคุณ</h2><div class="learning-results"><div>ก่อนเรียน <strong>${pre.length?pre.filter(a=>a.correct).length+' / '+d.lesson.questions.length:'ยังไม่ได้ตอบ'}</strong><span>ส่ง ${pre.length} ข้อ</span></div><div>หลังเรียน <strong>${post.length?post.filter(a=>a.correct).length+' / '+d.lesson.questions.length:'ยังไม่ได้ตอบ'}</strong><span>ส่ง ${post.length} ข้อ</span></div></div></section>${d.phase==='reflection'?`<form id="reflectionForm" class="lesson-card"><h2>สะท้อนคิดจากภารกิจ</h2><label>ใช้ความรู้จากบทเรียนตัดสินใจเรื่องใด? ยกตัวอย่าง<textarea id="reflectionKnowledge" required maxlength="600" rows="3">${esc(reflectionDraft.knowledge)}</textarea></label><label>ทีมทำอะไรได้ดี และรอบหน้าจะปรับอะไร?<textarea id="reflectionTeam" required maxlength="600" rows="3">${esc(reflectionDraft.teamwork)}</textarea></label><button type="submit" class="lesson-primary">บันทึกสะท้อนคิด</button>${d.student.reflection?'<p class="answer-saved">บันทึกแล้ว แก้ไขได้จนกว่าครูจบกิจกรรม</p>':''}</form>`:`<section class="lesson-card"><h2>กิจกรรมจบแล้ว</h2><p>${esc(saved.knowledge||'ยังไม่ได้ส่งสะท้อนคิด')}</p><p>${esc(saved.teamwork||'')}</p><button id="finishClassHome">กลับหน้าเลือกโหมด</button></section>`}`;}
    if(['reflection','finished'].includes(d.phase))body+=window.RiftLessonReview.render(d,esc);
    $('studentClassContent').innerHTML=`<div class="student-lesson-heading"><span>${esc(d.student.name)} · ห้อง ${d.code} · สนาม ${d.student.arena+1}</span><h2>${esc(d.title)}</h2><span class="phase-pill">${phases[d.phase]}</span></div>${body}`;
    root.querySelectorAll('[data-answer-question]').forEach(b=>b.onclick=async()=>{const questionId=b.dataset.answerQuestion;root.querySelectorAll(`[data-answer-question="${questionId}"]`).forEach(x=>x.disabled=true);try{await lessonRequest(`classes/${d.code}/answer`,'POST',{questionId,answer:Number(b.dataset.choice),stage:d.phase,round:d.round});renderKey='';await pollStudent();}catch(e){message(e.message);root.querySelectorAll(`[data-answer-question="${questionId}"]`).forEach(x=>x.disabled=false);}});
    if($('returnClassGame'))$('returnClassGame').onclick=()=>{education.panelOpen=false;root.hidden=true;document.body.classList.remove('education-open');};if($('finishClassHome'))$('finishClassHome').onclick=home;
    if($('reflectionForm')){$('reflectionKnowledge').oninput=()=>reflectionDraft.knowledge=$('reflectionKnowledge').value;$('reflectionTeam').oninput=()=>reflectionDraft.teamwork=$('reflectionTeam').value;$('reflectionForm').onsubmit=async e=>{e.preventDefault();try{await lessonRequest(`classes/${d.code}/reflection`,'POST',reflectionDraft);renderKey='';await pollStudent();message('บันทึกสะท้อนคิดแล้ว');}catch(e){message(e.message);}};}
  }
  window.riftJoinClassroom=code=>{home('student');$('classCode').value=code;message('อ่าน QR แล้ว กรอกชื่อ เลือกฮีโร่ แล้วกดเข้าห้องเรียน');};
  $('classroomMode').onclick=home;bar.onclick=()=>{education.panelOpen=true;root.hidden=false;document.body.classList.add('education-open');if(education.details)renderStudent(education.details);};
  window.riftLessonChanged=c=>{education.details={...education.details,...c};if(c.phase!=='play'||c.paused){if(game)game.paused=true;root.hidden=false;document.body.classList.add('education-open');}else if(root.hidden)document.body.classList.remove('education-open');};window.riftLessonError=message;window.riftOpenLesson=()=>{education.panelOpen=true;root.hidden=false;document.body.classList.add('education-open');$('result').hidden=true;if(education.details)renderStudent(education.details);};
  if(education.session&&sessionStorage.getItem('rift.classActive')!=='0'&&!sessionStorage.getItem(ROOM_STORAGE))void studentHome();else if(new URLSearchParams(location.search).has('class'))home('student');
})();
